[metadata] {"filePath": "/workspace/repo/crates/polars-compute/src/cast/binview_to.rs", "oldString": "pub fn utf8view_to_utf8<O: Offset>(array: &Utf8ViewArray) -> Utf8Array<O> {", "newString": "/// Cast a [`BinaryViewArray`] to a [`FixedSizeBinaryArray`] of the given `size`.
///
/// Nulls are preserved. Errors with a [`ComputeError`] if any non-null value does not have a
/// byte length equal to `size`.
///
/// [`ComputeError`]: polars_error::PolarsError::ComputeError
pub fn binview_to_fixed_size_binary(
    array: &BinaryViewArray,
    size: usize,
) -> PolarsResult<FixedSizeBinaryArray> {
    let len = Array::len(array);
    let mut values: Vec<u8> = Vec::with_capacity(len * size);

    for (i, opt_slice) in array.iter().enumerate() {
        match opt_slice {
            Some(slice) => {
                if slice.len() != size {
                    return Err(polars_err!(
                        ComputeError:
                        "bytes at index {i} had mismatching length {}, expected {size}",
                        slice.len(),
                    ));
                }
                values.extend_from_slice(slice);
            },
            None => values.resize(values.len() + size, 0),
        }
    }

    FixedSizeBinaryArray::try_new(
        ArrowDataType::FixedSizeBinary(size),
        values.into(),
        array.validity().cloned(),
    )
}

